// AccountingConnectionScopeTenant restricts a query to a single tenant by adding:
//
//	WHERE acctc.organization_id = ? AND acctc.business_unit_id = ?
//
// Returns the same *bun.SelectQuery so it can be chained fluently:
//
//	buncolgen.AccountingConnectionScopeTenant(sq, ti).
//		Where(buncolgen.AccountingConnectionColumns.ID.Eq(), id)
func AccountingConnectionScopeTenant(q *bun.SelectQuery, ti pagination.TenantInfo) *bun.SelectQuery {
	return ScopeTenant(q, AccountingConnectionColumns.OrganizationID, AccountingConnectionColumns.BusinessUnitID, ti)
}

// AccountingConnectionScopeTenantUpdate restricts an update query to a single tenant.
// Use this inside UpdateQuery.WhereGroup callbacks:
//
//	WhereGroup(" AND ", func(uq *bun.UpdateQuery) *bun.UpdateQuery {
//		return buncolgen.AccountingConnectionScopeTenantUpdate(uq, req.TenantInfo).
//			Where(buncolgen.AccountingConnectionColumns.ID.In(), bun.List(ids))
//	})
func AccountingConnectionScopeTenantUpdate(q *bun.UpdateQuery, ti pagination.TenantInfo) *bun.UpdateQuery {
	return ScopeTenantUpdate(q, AccountingConnectionColumns.OrganizationID, AccountingConnectionColumns.BusinessUnitID, ti)
}

// AccountingConnectionScopeTenantDelete restricts a delete query to a single tenant.
// Use this inside DeleteQuery.WhereGroup callbacks:
//
//	WhereGroup(" AND ", func(dq *bun.DeleteQuery) *bun.DeleteQuery {
//		return buncolgen.AccountingConnectionScopeTenantDelete(dq, req.TenantInfo).
//			Where(buncolgen.AccountingConnectionColumns.ID.Eq(), id)
//	})
func AccountingConnectionScopeTenantDelete(q *bun.DeleteQuery, ti pagination.TenantInfo) *bun.DeleteQuery {
	return ScopeTenantDelete(q, AccountingConnectionColumns.OrganizationID, AccountingConnectionColumns.BusinessUnitID, ti)
}

// AccountingConnectionApplyTenant returns a closure for SelectQuery.Apply() that scopes to a single tenant.
// Use this instead of wrapping ScopeTenant in an anonymous function:
//
//	q.Apply(buncolgen.AccountingConnectionApplyTenant(tenantInfo))
func AccountingConnectionApplyTenant(ti pagination.TenantInfo) func(*bun.SelectQuery) *bun.SelectQuery {
	return ApplyTenant(AccountingConnectionColumns.OrganizationID, AccountingConnectionColumns.BusinessUnitID, ti)
}

